INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Rotting tomatoes is a chemical change because new substances are formed.', 'True', 'False', 'True', 'Rotting involves decomposition, producing new substances.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Crushing chunks of ice is a chemical change because its shape changes.', 'True', 'False', 'False', 'Crushing ice only changes its size and shape. The substance remains water.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'A chemical change produces one or more new substances.', 'True', 'False', 'True', 'The chemical composition changes during a chemical change.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Gas bubbles produced when vinegar reacts with baking soda are evidence of a chemical reaction.', 'True', 'False', 'True', 'The bubbles are carbon dioxide gas formed during the reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Curdling of milk is considered evidence of gas formation.', 'True', 'False', 'False', 'It is evidence of precipitate formation, where solid curds are produced.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'If a container becomes hot after quicklime is mixed with water, a chemical reaction has occurred.', 'True', 'False', 'True', 'The release of heat indicates an exothermic chemical reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Simply cutting paper is evidence that a chemical reaction occurred.', 'True', 'False', 'False', 'Cutting only changes the paper''s shape, not its composition.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'When two clear liquids produce a solid that settles at the bottom, a precipitate has formed.', 'True', 'False', 'True', 'A precipitate is an insoluble solid formed during a reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'A downward arrow (↓) beside a product indicates that a gas is released.', 'True', 'False', 'False', 'A downward arrow indicates the formation of a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Neutralization is classified as a special type of combination reaction.', 'True', 'False', 'False', 'It is a special type of double displacement reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Milk of magnesia contains sodium hydroxide.', 'True', 'False', 'False', 'It contains magnesium hydroxide, Mg(OH)₂.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Onion and vanilla are examples of synthetic indicators.', 'True', 'False', 'False', 'They are olfactory indicators because they change smell in acids and bases.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Carbon dioxide has the chemical formula CO₂.', 'True', 'False', 'True', 'It contains one carbon atom and two oxygen atoms.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'In 2H₂SO₄, there are four hydrogen atoms in total.', 'True', 'False', 'True', 'Two molecules each contain two hydrogen atoms (2 × 2 = 4).', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'In 4Al₂O₃, there are eight oxygen atoms altogether .', 'True', 'False', 'False', 'There are 12 oxygen atoms (4 × 3 = 12).', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'In 5C₆H₁₂O₆, there are 30 carbon atoms in total.', 'True', 'False', 'True', 'Five molecules each contain six carbon atoms (5 × 6 = 30).', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'If 12 g of carbon reacts completely with 32 g of oxygen, the total mass of carbon dioxide produced is 44 g.', 'True', 'False', 'True', 'The masses of the reactants add up to the mass of the products.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'The reaction arrow (→) means "reacts to form" or "produces."', 'True', 'False', 'True', 'It shows the direction of the chemical reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'An exothermic reaction absorbs heat from its surroundings.', 'True', 'False', 'False', 'Exothermic reactions release heat or light energy.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Endothermic reactions absorb energy from their surroundings.', 'True', 'False', 'True', 'These reactions require an input of energy.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'An insoluble solid formed during a reaction is called a precipitate.', 'True', 'False', 'True', 'Precipitates are often indicated by (s) or a downward arrow (↓).', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Chemical formulas are used because they show the types and numbers of atoms in a substance.', 'True', 'False', 'True', 'Formulas provide exact information about chemical composition.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Endothermic reactions release heat to their surroundings.', 'True', 'False', 'False', 'Endothermic reactions absorb heat from their surroundings.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Exothermic reactions release heat energy into the surroundings.', 'True', 'False', 'True', 'Combustion and neutralization are common examples of exothermic reactions.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'The fire triangle is made up of fuel, oxygen, and carbon dioxide.', 'True', 'False', 'False', 'The fire triangle consists of fuel, oxygen, and heat.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Refrigeration preserves food by slowing down chemical reactions and microbial activity.', 'True', 'False', 'True', 'Lower temperatures reduce the rate of spoilage reactions.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Burning wood is an example of an exothermic reaction.', 'True', 'False', 'True', 'Burning releases heat and light energy.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Crushing a tablet into powder usually makes it dissolve faster.', 'True', 'False', 'True', 'Crushing increases surface area, allowing faster interaction with the solvent.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Larger pieces of charcoal burn faster than powdered charcoal.', 'True', 'False', 'False', 'Powdered charcoal has greater surface area and burns more quickly.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Water extinguishes most fires mainly by removing oxygen from the flame.', 'True', 'False', 'False', 'Water primarily cools the fuel below its ignition temperature.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'A fire blanket extinguishes fire by cutting off the oxygen supply.', 'True', 'False', 'True', 'Smothering the fire prevents oxygen from reaching it.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Painting iron helps prevent rusting by reducing contact with oxygen and water.', 'True', 'False', 'True', 'The paint acts as a protective barrier.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Explosions are examples of extremely fast chemical reactions.', 'True', 'False', 'True', 'They occur rapidly and release large amounts of energy in a short time.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Galvanizing iron protects it from corrosion by coating it with zinc.', 'True', 'False', 'True', 'Zinc acts as a protective layer and corrodes before the iron does.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Effectors detect changes in the body''s internal environment.', 'True', 'False', 'False', 'Receptors detect changes, while effectors carry out the response.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'When you are cold, the blood vessels in your skin widen to release more heat.', 'True', 'False', 'False', 'They constrict to reduce heat loss.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'When blood sugar rises, the pancreas releases glucagon.', 'True', 'False', 'False', 'The pancreas releases insulin to lower blood glucose levels.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'When blood sugar falls, the pancreas releases glucagon.', 'True', 'False', 'True', 'Glucagon stimulates the release of stored glucose from the liver.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'When blood pressure rises above normal, the body attempts to lower it back to its set point.', 'True', 'False', 'True', 'Negative feedback mechanisms work to return blood pressure to normal.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Dynamic equilibrium means the body''s internal conditions never change.', 'True', 'False', 'False', 'Dynamic equilibrium allows small fluctuations while remaining within a healthy range.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Diabetes is primarily associated with a failure in blood glucose regulation.', 'True', 'False', 'True', 'It results from problems with insulin production or insulin action.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Heredity allows useful traits to be passed from parents to offspring.', 'True', 'False', 'True', 'Evolution depends on inherited genetic traits.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Vestigial structures are body parts that have lost most or all of their original function.', 'True', 'False', 'True', 'Examples include the human appendix and tailbone.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Artificial selection occurs when nature determines which traits are inherited.', 'True', 'False', 'False', 'Artificial selection is controlled by humans through selective breeding.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Analogous structures perform similar functions but evolved independently.', 'True', 'False', 'True', 'They do not indicate a recent common ancestor.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Giraffes developed long necks because they stretched them during their lifetime.', 'True', 'False', 'False', 'Long-necked individuals survived and reproduced more successfully over many generations.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Choosing only the largest mangoes to plant is an example of artificial selection.', 'True', 'False', 'True', 'Humans intentionally select desirable traits.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'Vestigial pelvic bones in modern whales provide evidence that whales evolved from four-legged land mammals.', 'True', 'False', 'True', 'Fossil evidence and comparative anatomy support this evolutionary history.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'post_test', 'In science, the word "theory" means a simple guess with little supporting evidence.', 'True', 'False', 'False', 'A scientific theory is a well-tested explanation supported by extensive evidence.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'The reaction 2Na + Cl₂ → 2NaCl is an example of decomposition.', 'True', 'False', 'False', 'It is a combination (synthesis) reaction because two reactants form one product.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'The reaction CaCO₃ → CaO + CO₂ is a decomposition reaction.', 'True', 'False', 'True', 'One compound breaks down into two simpler substances.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'In a single displacement reaction, one element replaces another element in a compound.', 'True', 'False', 'True', 'This is the defining characteristic of single displacement.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Double displacement reactions involve one element replacing another element.', 'True', 'False', 'False', 'They involve two compounds exchanging ions.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'The reaction AgNO₃ + NaCl → AgCl + NaNO₃ is a double displacement reaction.', 'True', 'False', 'True', 'The ions exchange partners to form new compounds.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Oxygen gas is always a reactant in combustion reactions.', 'True', 'False', 'True', 'Combustion requires oxygen to occur.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Fuel reacting with oxygen to produce carbon dioxide and water is called combustion.', 'True', 'False', 'True', 'This is the general form of a combustion reaction.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'The reaction 2H₂O₂ → 2H₂O + O₂ is a synthesis reaction.', 'True', 'False', 'False', 'It is a decomposition reaction because one compound breaks apart.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Double displacement reactions involve the exchange of ions between two compounds.', 'True', 'False', 'True', 'The ions switch partners to form new compounds.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Iron reacting with sulfur to form iron sulfide is an example of synthesis.', 'True', 'False', 'True', 'Two reactants combine to form one compound.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'A decomposition reaction combines two substances to form one product.', 'True', 'False', 'False', 'Decomposition involves one compound breaking into simpler substances.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'In a single displacement reaction, two compounds exchange ions.', 'True', 'False', 'False', 'Single displacement involves one element replacing another in a compound.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Double displacement reactions involve two compounds exchanging ions.', 'True', 'False', 'True', 'The products are formed by swapping ions between compounds.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Oxygen gas is always a reactant in combustion reactions.', 'True', 'False', 'True', 'Combustion requires oxygen to occur.', true),
('b0000000-0000-0000-0000-000000000102', 2, 'post_test', 'Increasing the amount of oxygen can make combustion occur more rapidly.', 'True', 'False', 'True', 'More oxygen increases the frequency of effective combustion reactions.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Photosynthesis is a physical change because plants only absorb sunlight.', 'True', 'False', 'False', 'Photosynthesis is a chemical reaction that produces glucose and oxygen.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Combustion of hydrocarbons always produces salt and water.', 'True', 'False', 'False', 'It produces carbon dioxide and water.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Neutralization reactions produce salt and water.', 'True', 'False', 'True', 'They occur when an acid reacts with a base.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Melting wax is an example of a physical change.', 'True', 'False', 'True', 'Only the state changes; no new substance is formed.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Salt dissolving in water is evidence of a chemical reaction.', 'True', 'False', 'False', 'Dissolving salt is a physical change.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'All acids have a sour taste and turn blue litmus paper red.', 'True', 'False', 'True', 'These are characteristic properties of acids.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Bases turn blue litmus paper red.', 'True', 'False', 'False', 'Bases turn red litmus paper blue.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Pure water has a pH of 7, making it neutral.', 'True', 'False', 'True', 'A pH of 7 indicates a neutral solution.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Phenolphthalein is pink in acidic solutions.', 'True', 'False', 'False', 'Phenolphthalein is colorless in acids and pink in bases.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Acids release hydrogen ions (H⁺) when dissolved in water.', 'True', 'False', 'True', 'This follows the Arrhenius definition of acids.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Bases release hydrogen ions (H⁺) in water.', 'True', 'False', 'False', 'Bases release hydroxide ions (OH⁻).', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Sodium chloride (NaCl) is the chemical name for common table salt.', 'True', 'False', 'True', 'Sodium chloride is a neutral salt commonly used as table salt.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Hydrochloric acid found in the stomach has the formula H₂SO₄.', 'True', 'False', 'False', 'The correct formula is HCl.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Sodium hydroxide (NaOH) is a strong base commonly known as lye.', 'True', 'False', 'True', 'NaOH is also called caustic soda or lye.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Methyl orange is yellow in acids and red in bases.', 'True', 'False', 'False', 'Methyl orange is red in acids and yellow in bases.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Turmeric is considered a natural acid-base indicator.', 'True', 'False', 'True', 'Turmeric changes color in basic solutions.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'A solution with a pH of 7 is acidic.', 'True', 'False', 'False', 'A pH of 7 is neutral.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Vinegar contains acetic acid.', 'True', 'False', 'True', 'Acetic acid gives vinegar its sour taste.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Blue litmus paper remains blue when placed in a basic solution.', 'True', 'False', 'True', 'Bases do not change the color of blue litmus paper.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Hydrochloric acid, vinegar, and calamansi juice are all examples of acids.', 'True', 'False', 'True', 'All three exhibit acidic properties.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Sodium hydroxide, bleach, and milk of magnesia are examples of bases.', 'True', 'False', 'True', 'These substances are classified as bases.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Antacids relieve hyperacidity because they are weak acids.', 'True', 'False', 'False', 'Antacids are mild bases that neutralize excess stomach acid.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'A solution with a pH of 4 is acidic.', 'True', 'False', 'True', 'Any pH below 7 is acidic.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'A solution with a pH of 11 is acidic.', 'True', 'False', 'False', 'A pH above 7 indicates a basic or alkaline solution.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Among pH 1, pH 3, and pH 6, pH 6 is the weakest acid.', 'True', 'False', 'True', 'It is closest to neutral (pH 7).', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'A neutralization reaction produces salt and water from an acid and a base.', 'True', 'False', 'True', 'This is the general equation for neutralization.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Turmeric turns reddish-brown when exposed to a base such as soap.', 'True', 'False', 'True', 'This color change indicates the presence of a base.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Tooth enamel begins to dissolve when the pH in the mouth drops below 5.5.', 'True', 'False', 'True', 'Low pH increases the risk of tooth decay.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Sodium carbonate (Na₂CO₃) forms an acidic solution in water.', 'True', 'False', 'False', 'It forms a basic solution.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Ammonium chloride (NH₄Cl) forms an acidic solution when dissolved in water .', 'True', 'False', 'True', 'NH₄Cl is an acidic salt.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Dry hydrogen chloride gas changes dry blue litmus paper to red immediately.', 'True', 'False', 'False', 'Water is needed for HCl to release hydrogen ions.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Each pH unit represents a tenfold change in hydrogen ion concentration.', 'True', 'False', 'True', 'The pH scale is logarithmic.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'In the order pH 2, pH 6, pH 7, pH 9, and pH 12, pH 12 is the strongest acid.', 'True', 'False', 'False', 'pH 12 is the strongest base, while pH 2 is the strongest acid.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Sodium chloride (NaCl) is produced from a strong acid and a strong base and is generally neutral.', 'True', 'False', 'True', 'HCl reacts with NaOH to produce NaCl and water.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Acidic and basic solutions can conduct electricity because they contain mobile ions.', 'True', 'False', 'True', 'The movement of ions allows electric current to flow.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'When diluting concentrated acid, water should always be poured into the acid.', 'True', 'False', 'False', 'Acid should always be added slowly to water to prevent splashing.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Acetic acid (CH₃COOH) is the weak acid present in vinegar.', 'True', 'False', 'True', 'It is responsible for vinegar''s acidic properties.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Baking soda reacts with acids to release oxygen gas.', 'True', 'False', 'False', 'It releases carbon dioxide (CO₂) gas during the reaction.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Chemical equations are used only to represent physical changes.', 'True', 'False', 'False', 'They represent chemical changes where new substances are formed.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Rusting of iron is a physical change because no new substance is produced.', 'True', 'False', 'False', 'Rusting is a chemical change that forms iron oxide.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Powdered calcium carbonate reacts more quickly with hydrochloric acid than marble chips.', 'True', 'False', 'True', 'Powder has a much greater surface area exposed to the acid.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Salting and sugaring preserve food by reducing the amount of available water for microorganisms.', 'True', 'False', 'True', 'Microorganisms need water to survive and multiply.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Photosynthesis is an endothermic reaction because it absorbs energy from sunlight.', 'True', 'False', 'True', 'Light energy is required to convert carbon dioxide and water into glucose.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Photosynthesis is an exothermic reaction because it releases heat.', 'True', 'False', 'False', 'Photosynthesis absorbs energy, making it endothermic.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Blood glucose, blood pH, and body temperature are regulated by homeostasis.', 'True', 'False', 'True', 'These are important internal conditions that must remain within healthy limits.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'The kidneys help maintain the body''s water and salt balance.', 'True', 'False', 'True', 'They adjust urine concentration to regulate fluid balance.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'If blood pH is not properly regulated, enzymes may stop functioning correctly.', 'True', 'False', 'True', 'Incorrect pH can change enzyme shape and reduce their activity.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Biogeography is the study of fossils found in sedimentary rocks.', 'True', 'False', 'False', 'Biogeography studies the distribution of organisms across Earth.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'Geographic isolation occurs when a physical barrier separates populations.', 'True', 'False', 'True', 'Mountains, rivers, or oceans can prevent populations from interbreeding.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'A species found naturally only in one geographic area is called endemic.', 'True', 'False', 'True', 'The Philippine Eagle is an example of an endemic species.', true),
('b0000000-0000-0000-0000-000000000103', 2, 'post_test', 'The correct sequence for speciation is Variation → Geographic Isolation → Natural Selection → Reproductive Isolation → New Species.', 'True', 'False', 'True', 'These processes gradually lead to the formation of new species.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Reactants are written on the right side of a chemical equation.', 'True', 'False', 'False', 'Reactants are written on the left side of the reaction arrow.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Products are the new substances formed during a chemical reaction.', 'True', 'False', 'True', 'Products appear on the right side of the chemical equation.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (aq) means the substance is in the gaseous state.', 'True', 'False', 'False', '(aq) means the substance is dissolved in water.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol Δ above a reaction arrow means heat is supplied to the reaction.', 'True', 'False', 'True', 'Delta (Δ) indicates that heating is required.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The plus (+) sign in a chemical equation means the substances are mixed or react together.', 'True', 'False', 'True', 'It is read as "reacts with" or "and."', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'A combination reaction follows the general equation A + B → AB.', 'True', 'False', 'True', 'Two or more reactants combine to form a single product.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The general equation AB → A + B represents a combination reaction.', 'True', 'False', 'False', 'It represents decomposition.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'In the equation Mg + O₂ → MgO, magnesium oxide is the product.', 'True', 'False', 'True', 'Products are found on the right side of the arrow.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The arrow (→) in a chemical equation means "yields" or "produces."', 'True', 'False', 'True', 'It separates reactants from products.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (g) or an upward arrow (↑) indicates that a solid has formed.', 'True', 'False', 'False', 'It indicates that a gas is produced. TRUE OR FALSE : topic 3 :Acids, Bases, and Salts', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Reactants are written on the left side of a chemical equation.', 'True', 'False', 'True', 'Reactants are the starting substances before the reaction occurs.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Products are found on the left side of the reaction arrow.', 'True', 'False', 'False', 'Products are written on the right side of the arrow because they are formed after the reaction.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (aq) means a substance is dissolved in water.', 'True', 'False', 'True', '"Aqueous" means the substance is in a water solution.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (s) represents a gas.', 'True', 'False', 'False', '(s) stands for solid.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (g) indicates that a substance is in the gaseous state.', 'True', 'False', 'True', '(g) is the standard symbol for gases.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The arrow (→) in a chemical equation is read as "yields" or "produces."', 'True', 'False', 'True', 'It separates the reactants from the products.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The plus (+) sign between reactants means "reacts with" or "and."', 'True', 'False', 'True', 'It indicates that substances are combined in the reaction.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'A balanced chemical equation has the same number of atoms of each element on both sides.', 'True', 'False', 'True', 'This follows the Law of Conservation of Mass.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The balanced equation for forming water is H₂ + O → H₂O.', 'True', 'False', 'False', 'The correct balanced equation is 2H₂ + O₂ → 2H₂O.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (l) indicates that a substance is in the liquid state.', 'True', 'False', 'True', '(l) stands for liquid.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The equation Ca + Cl₂ → CaCl₂ is already balanced.', 'True', 'False', 'True', 'There is one calcium atom and two chlorine atoms on both sides.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'In the equation Mg + 2HCl → MgCl₂ + H₂, the product side contains two chlorine atoms.', 'True', 'False', 'True', 'The subscript 2 in MgCl₂ represents two chlorine atoms.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Chemical equations are balanced mainly to make them easier to read.', 'True', 'False', 'False', 'They are balanced to obey the Law of Conservation of Mass.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'In the equation N₂ + H₂ → NH₃, both nitrogen and hydrogen atoms are initially unbalanced.', 'True', 'False', 'True', 'Both elements must be balanced by adjusting coefficients.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The balanced equation for forming water is 2H₂ + O₂ → 2H₂O.', 'True', 'False', 'True', 'This equation has equal numbers of hydrogen and oxygen atoms on both sides.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The balanced equation 2Al + O₂ → Al₂O₃ correctly balances aluminum and oxygen atoms.', 'True', 'False', 'False', 'The correct balanced equation is 4Al + 3O₂ → 2Al₂O₃.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'In the balanced equation 2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O, there are 14 oxygen atoms on the reactant side.', 'True', 'False', 'True', 'Seven oxygen molecules contain 14 oxygen atoms.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Balanced chemical equations show that atoms are rearranged, not created or destroyed.', 'True', 'False', 'True', 'This is the principle behind the Law of Conservation of Mass.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Reactants are the substances present before a chemical reaction begins.', 'True', 'False', 'True', 'Reactants are the starting materials found on the left side of the equation.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Products are written on the left side of the reaction arrow.', 'True', 'False', 'False', 'Products are written on the right side because they are formed after the reaction.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (s) indicates that a substance is dissolved in water.', 'True', 'False', 'False', '(s) means the substance is in the solid state.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (aq) means the substance is dissolved in water.', 'True', 'False', 'True', '"Aqueous" refers to a solution in water.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'A combination reaction produces one product from two or more reactants.', 'True', 'False', 'True', 'Its general form is A + B → AB.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol Δ above a reaction arrow means that heat is applied.', 'True', 'False', 'True', 'Delta (Δ) indicates heating during the reaction.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Word equations use names of substances, while chemical equations use formulas and symbols.', 'True', 'False', 'True', 'Chemical equations provide a more precise representation of reactions.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'A typical chemical equation directly shows how fast a reaction occurs.', 'True', 'False', 'False', 'It shows the substances involved, not the reaction rate.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'A reversible reaction is represented by the symbol ⇌.', 'True', 'False', 'True', 'This symbol indicates the reaction can proceed in both directions.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'Even if a chemical equation is not balanced, it can still identify the reactants, products, and reaction type.', 'True', 'False', 'True', 'Balancing affects quantity, not the identity of the substances.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The reaction arrow (→) means the reactants and products are always equal in every way.', 'True', 'False', 'False', 'The arrow indicates the direction of the reaction, not equality.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The symbol (g) beside a product indicates that a gas is produced.', 'True', 'False', 'True', '(g) represents the gaseous state.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'The main purpose of a chemical equation is to summarize a chemical reaction using standard symbols and formulas.', 'True', 'False', 'True', 'It clearly shows the reactants, products, and direction of the reaction. Certainly! Here''s Part 6 in the same format as Parts 1–5.', true),
('b0000000-0000-0000-0000-000000000104', 2, 'post_test', 'A chemical reaction stops when all of the reactants have been consumed.', 'True', 'False', 'True', 'Without reactants, no further reaction can occur.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'The Law of Conservation of Mass states that mass can be created during a chemical reaction.', 'True', 'False', 'False', 'Mass is neither created nor destroyed; the total mass of reactants equals the total mass of products.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'A coefficient tells the number of molecules or moles involved in a reaction.', 'True', 'False', 'True', 'It multiplies the entire chemical formula.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'A subscript tells the number of molecules present in a reaction.', 'True', 'False', 'False', 'A subscript tells the number of atoms of a particular element in one molecule or formula unit.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'In CaCl₂, the subscript "2" refers to the number of chlorine atoms.', 'True', 'False', 'True', 'There are two chlorine atoms bonded to one calcium atom.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'When balancing chemical equations, only coefficients should be changed.', 'True', 'False', 'True', 'Changing subscripts changes the identity of the substance.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'In 3H₂O, the number 3 is a subscript.', 'True', 'False', 'False', 'The number 3 is a coefficient, while the 2 is a subscript.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'The first step in balancing a chemical equation is to count the atoms on both sides.', 'True', 'False', 'True', 'Counting atoms helps determine which coefficients need adjustment.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'If gas escapes from an open container during a reaction, the Law of Conservation of Mass is still valid.', 'True', 'False', 'True', 'The gas escaped the container, but the total mass of all matter remains unchanged.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'Changing subscripts is an acceptable method for balancing chemical equations.', 'True', 'False', 'False', 'Changing subscripts changes the chemical substance itself.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'The balanced equation N₂ + 3H₂ → 2NH₃ correctly follows the Law of Conservation of Mass.', 'True', 'False', 'True', 'Both sides contain two nitrogen atoms and six hydrogen atoms.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'The balanced equation 3Fe + 4H₂O → Fe₃O₄ + 4H₂ obeys the Law of Conservation of Mass.', 'True', 'False', 'True', 'The number of each type of atom is equal on both sides.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'Changing subscripts while balancing an equation is acceptable because it does not change the identity of a substance.', 'True', 'False', 'False', 'Changing subscripts changes the chemical formula and creates a different substance.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'A coefficient is the small number written below an element symbol.', 'True', 'False', 'False', 'A coefficient is the large number placed before a chemical formula.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'A subscript tells the number of atoms of an element in one molecule or formula unit.', 'True', 'False', 'True', 'Subscripts are part of a compound''s chemical formula.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'The Law of Conservation of Mass states that the total mass of the reactants equals the total mass of the products.', 'True', 'False', 'True', 'Atoms are rearranged but are neither created nor destroyed.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'Subscripts can be changed when balancing equations because they do not affect the identity of a substance.', 'True', 'False', 'False', 'Changing a subscript changes the chemical formula and creates a different substance.', true),
('b0000000-0000-0000-0000-000000000105', 2, 'post_test', 'A coefficient applies to the entire chemical formula that follows it.', 'True', 'False', 'True', 'It multiplies every atom in the formula.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'A catalyst speeds up a reaction without being used up or permanently changed.', 'True', 'False', 'True', 'Catalysts lower the activation energy of a reaction.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Reaction rate refers to how fast a chemical reaction takes place.', 'True', 'False', 'True', 'The rate of reaction measures how quickly reactants are converted into products.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Increasing the temperature usually slows down the rate of a chemical reaction.', 'True', 'False', 'False', 'Higher temperatures increase particle movement, leading to more frequent and energetic collisions.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'A catalyst speeds up a chemical reaction without being permanently consumed.', 'True', 'False', 'True', 'Catalysts lower the activation energy needed for a reaction.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Increasing the surface area of a solid reactant generally increases the reaction rate.', 'True', 'False', 'True', 'More surface area allows more particles to collide at the same time.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'An inhibitor increases the rate of a chemical reaction.', 'True', 'False', 'False', 'Inhibitors slow down or prevent chemical reactions.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Activation energy is the minimum amount of energy required for a reaction to occur.', 'True', 'False', 'True', 'Reacting particles must overcome this energy barrier.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'According to collision theory, every collision between particles produces a reaction.', 'True', 'False', 'False', 'Only effective collisions with enough energy and proper orientation produce reactions.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Lowering the temperature decreases the reaction rate of most chemical reactions.', 'True', 'False', 'True', 'Lower temperatures reduce particle movement and collision frequency.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Increasing the concentration of reactants generally increases the rate of reaction.', 'True', 'False', 'True', 'More particles are available to collide each second.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Enzymes are biological catalysts found in living organisms.', 'True', 'False', 'True', 'They speed up biochemical reactions without being consumed.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Canning preserves food mainly by increasing its surface area.', 'True', 'False', 'False', 'Canning uses heat to destroy microorganisms and seals the food to prevent contamination.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Stirring reactants can increase the rate of a chemical reaction.', 'True', 'False', 'True', 'Stirring brings reactant particles into contact more frequently.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Higher temperatures increase reaction rates only because particles collide more often.', 'True', 'False', 'False', 'They also increase the number of particles with enough energy to overcome activation energy.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Catalysts provide an alternative reaction pathway with lower activation energy.', 'True', 'False', 'True', 'This allows reactions to occur more quickly.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Catalytic converters reduce harmful vehicle emissions by using catalysts.', 'True', 'False', 'True', 'They convert harmful gases into less harmful substances before they are released.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'During exercise, breathing rate increases to help maintain oxygen and carbon dioxide balance.', 'True', 'False', 'True', 'Faster breathing supplies more oxygen and removes excess carbon dioxide.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Similar early embryos of vertebrates provide evidence of common ancestry.', 'True', 'False', 'True', 'Comparative embryology supports evolutionary relationships.', true),
('b0000000-0000-0000-0000-000000000106', 2, 'post_test', 'Reproductive isolation occurs only when a mountain or river separates populations.', 'True', 'False', 'False', 'Reproductive isolation can also result from differences in behavior, breeding season, or mating patterns.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Homeostasis is the maintenance of a stable internal environment despite changes in the external environment.', 'True', 'False', 'True', 'Homeostasis maintains dynamic internal balance even when external conditions change.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Homeostasis means the body remains completely unchanged at all times.', 'True', 'False', 'False', 'The body constantly makes small adjustments to keep conditions within a normal range.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'The nervous and endocrine systems are the main control systems involved in homeostasis.', 'True', 'False', 'True', 'The nervous system responds quickly, while the endocrine system provides longer-lasting regulation.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Sweating when body temperature rises is an example of positive feedback.', 'True', 'False', 'False', 'Sweating is a negative feedback mechanism because it helps return body temperature to normal.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'The normal target value maintained by homeostasis is called the set point.', 'True', 'False', 'True', 'Examples include normal body temperature and blood glucose level.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Muscles and glands are examples of effectors in homeostasis.', 'True', 'False', 'True', 'They perform actions that help restore normal conditions.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Negative feedback increases a change farther away from the set point.', 'True', 'False', 'False', 'Negative feedback reverses the change and restores balance.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Human height is maintained at a constant value through homeostasis.', 'True', 'False', 'False', 'Height naturally changes during growth and is not regulated as a homeostatic variable.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'The hypothalamus is the primary control center for body temperature regulation.', 'True', 'False', 'True', 'It receives information from receptors and coordinates appropriate responses.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Hormones are chemical messengers produced by the endocrine system.', 'True', 'False', 'True', 'Hormones help regulate many body processes over longer periods.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Insulin and glucagon work together to regulate blood glucose levels.', 'True', 'False', 'True', 'They have opposite effects that keep blood sugar within the normal range.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Shivering is an example of negative feedback that helps restore body temperature.', 'True', 'False', 'True', 'Muscle contractions generate heat to raise body temperature.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Maintaining a constant body weight is one of the main goals of homeostasis.', 'True', 'False', 'False', 'Body weight naturally changes and is not a fixed homeostatic set point.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Insulin lowers blood glucose, while glucagon raises it.', 'True', 'False', 'True', 'These hormones have opposite actions to maintain stable blood sugar.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Positive feedback amplifies a change instead of reversing it.', 'True', 'False', 'True', 'Positive feedback continues until a specific event is completed.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Blood clotting is an example of positive feedback.', 'True', 'False', 'True', 'Clotting chemicals activate more clotting until the wound is sealed.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Homeostasis requires energy to maintain stable internal conditions.', 'True', 'False', 'True', 'Active processes are needed to continuously regulate the body''s internal environment.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'The correct order of a homeostatic feedback loop is: Stimulus → Receptor → Control Center → Effector → Response.', 'True', 'False', 'True', 'This is the standard sequence of negative and positive feedback mechanisms.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Oxytocin causing stronger contractions during childbirth is an example of negative feedback.', 'True', 'False', 'False', 'It is positive feedback because the contractions become stronger until birth occurs.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Long-term failure of homeostasis can lead to disease, organ damage, or death.', 'True', 'False', 'True', 'Cells cannot function properly when internal conditions move outside safe limits.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Dehydration causes the kidneys to reabsorb more water into the bloodstream.', 'True', 'False', 'True', 'This helps restore normal water balance through negative feedback.', true),
('b0000000-0000-0000-0000-000000000107', 2, 'post_test', 'Without homeostasis, cells and organs cannot function properly.', 'True', 'False', 'True', 'Failure to maintain stable internal conditions can lead to severe damage or death.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Evolution is the gradual change in the inherited traits of a population over many generations.', 'True', 'False', 'True', 'Evolution occurs in populations over time through the inheritance of genetic traits.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Evolution occurs when an individual organism changes its traits during its lifetime.', 'True', 'False', 'False', 'Individuals may grow or adapt, but evolution occurs across generations in populations.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Charles Darwin proposed natural selection as the primary mechanism of evolution.', 'True', 'False', 'True', 'Darwin introduced the theory of natural selection in On the Origin of Species (1859).', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Gregor Mendel developed the theory of natural selection.', 'True', 'False', 'False', 'Mendel is known for his work on heredity and genetics, not natural selection.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Natural selection favors organisms that are better adapted to their environment.', 'True', 'False', 'True', 'Better-adapted organisms are more likely to survive and reproduce.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'The strongest organism always survives through natural selection.', 'True', 'False', 'False', 'Fitness refers to successful reproduction, not simply physical strength.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'An adaptation is an inherited trait that increases an organism''s chance of survival and reproduction.', 'True', 'False', 'True', 'Adaptations improve fitness in a particular environment.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Variation refers to similarities among individuals of the same species.', 'True', 'False', 'False', 'Variation describes the differences in inherited traits among individuals.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Fossils are preserved remains or traces of ancient organisms.', 'True', 'False', 'True', 'Fossils provide evidence of organisms that lived long ago.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Homologous structures have different evolutionary origins but identical functions.', 'True', 'False', 'False', 'Homologous structures share a common ancestry but may have different functions.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'The human arm, whale flipper, and bat wing are examples of homologous structures.', 'True', 'False', 'True', 'They share the same underlying bone structure inherited from a common ancestor.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'The peppered moth is a classic example of natural selection in action.', 'True', 'False', 'True', 'Dark-colored moths became more common during the Industrial Revolution because they were better camouflaged.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Bird wings and insect wings are homologous structures.', 'True', 'False', 'False', 'They are analogous structures because they have similar functions but different evolutionary origins.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Isolation can contribute to the formation of new species.', 'True', 'False', 'True', 'Preventing gene flow allows populations to evolve independently.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Fossils found in deeper rock layers are generally older than fossils found in upper layers.', 'True', 'False', 'True', 'Lower rock layers were formed earlier in Earth''s history.', true),
('b0000000-0000-0000-0000-000000000108', 2, 'post_test', 'Mutation alone consistently produces adaptations that perfectly match the environment.', 'True', 'False', 'False', 'Mutations create variation, but natural selection determines which traits become common.', true);
